<script setup>
import {onMounted,ref} from 'vue';import {useRouter} from 'vue-router';import {getAdminRefunds} from '../../api/refund'
const router=useRouter(),records=ref([]),total=ref(0),page=ref(1),status=ref('PENDING'),keyword=ref(''),loading=ref(false);const load=async()=>{loading.value=true;try{const d=(await getAdminRefunds({refundStatus:status.value||undefined,keyword:keyword.value||undefined,page:page.value,size:10})).data;records.value=d.records;total.value=d.total}finally{loading.value=false}};const search=()=>{page.value=1;load()};onMounted(load)
</script>
<template><el-card><template #header><div class="head"><b>退票审核</b><div><el-select v-model="status" clearable placeholder="全部状态" style="width:130px" @change="search"><el-option label="待审核" value="PENDING"/><el-option label="已通过" value="APPROVED"/><el-option label="已驳回" value="REJECTED"/></el-select><el-input v-model="keyword" placeholder="用户名/订单号" style="width:200px;margin-left:8px" @keyup.enter="search"/><el-button type="primary" @click="search">查询</el-button></div></div></template><el-table :data="records" v-loading="loading"><el-table-column prop="refundNo" label="退款编号" min-width="210"/><el-table-column prop="username" label="用户"/><el-table-column prop="orderNo" label="订单号" min-width="210"/><el-table-column label="金额"><template #default="{row}">￥{{Number(row.refundAmount).toFixed(2)}}</template></el-table-column><el-table-column prop="refundStatus" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="router.push(`/admin/refunds/${row.refundId}`)">审核/详情</el-button></template></el-table-column></el-table><el-pagination v-if="total>10" v-model:current-page="page" :total="total" :page-size="10" layout="prev,pager,next" @current-change="load"/></el-card></template>
<style scoped>.head{display:flex;justify-content:space-between;align-items:center}.el-pagination{margin-top:16px;justify-content:flex-end}</style>
